{"implementation": "def solve(case):
    import math

    # Validate top-level fields
    if 'threshold' not in case:
        raise ValueError('Missing required field: threshold')
    if 'calls' not in case:
        raise ValueError('Missing required field: calls')

    threshold = case['threshold']
    calls = case['calls']

    if not isinstance(threshold, (int, float)):
        raise TypeError('threshold must be numeric')
    if not isinstance(calls, list):
        raise TypeError('calls must be a list')

    accepted_call_ids = []
    diagnostics = []

    for call in calls:
        # Validate required per-call fields
        for field in ('call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable'):
            if field not in call:
                raise ValueError(f'Call missing required field: {field}')

        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        prediction_tokens = call['prediction_tokens']
        parseable = call['parseable']

        if not isinstance(loss_without, (int, float)):
            raise TypeError(f'loss_without_call must be numeric for call {call_id}')
        if not isinstance(loss_with, (int, float)):
            raise TypeError(f'loss_with_call must be numeric for call {call_id}')
        if not isinstance(prediction_tokens, int) or prediction_tokens < 1:
            raise ValueError(f'prediction_tokens must be a positive integer for call {call_id}')
        if not isinstance(parseable, bool):
            raise TypeError(f'parseable must be a boolean for call {call_id}')

        # Stronger counterfactual: gain = L(tokens without call) - L(tokens with call)
        gain = loss_without - loss_with

        # Normalize by prediction token count (weighted future-token loss)
        normalized_gain = gain / prediction_tokens

        # Inclusive threshold: accept if parseable AND normalized_gain >= threshold
        accepted = parseable and normalized_gain >= threshold

        if accepted:
            accepted_call_ids.append(call_id)

        # Round diagnostics to 8 decimal places for stable serialization
        diagnostics.append({
            'call_id': call_id,
            'gain': round(gain, 8),
            'normalized_gain': round(normalized_gain, 8),
            'parseable': parseable,
            'accepted': accepted
        })

    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }
